recipes.code:
{
  "inputs": [
    {
      "id": "odgs-api-key",
      "type": "promptString",
      "description": "Metric Provenance licence key for Pro/Enterprise tier tools (compile_regulation, check_drift, detect_conflicts, narrate_audit, discover_bindings, download_pack). Omit for community-tier access (validate_payload, governance_score, list_packs, conformance_check).",
      "password": true
    }
  ],
  "servers": {
    "odgs": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "odgs-mcp-server@0.3.3"
      ],
      "env": {
        "ODGS_PROJECT_ROOT": "<odgs-project-root>",
        "ODGS_API_KEY": "${input:odgs-api-key}"
      }
    }
  }
}
